(function() {
  window.CardSpoke.Plugin.register('kanban-board', {
    manifest: {
      name: 'Kanban Board',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Toggleable kanban view that groups cards by tag',
      layer: 'app',
      permissions: ['ui-override', 'storage']
    },
    setup: async function(ctx) {
      var self = this;
      self._kanbanActive = false;
      var toggle = document.createElement('button');
      toggle.className = 'kanban-toggle';
      toggle.textContent = 'Kanban View';
      document.body.appendChild(toggle);
      self._toggle = toggle;
      var view = document.createElement('div');
      view.className = 'kanban-view';
      view.id = 'kanban-view';
      document.body.appendChild(view);
      self._view = view;
      var defaultColumns = ['To Do', 'In Progress', 'Done'];
      function escapeHtml(str) {
        var div = document.createElement('div');
        div.textContent = str;
        return div.innerHTML;
      }
      function renderKanban() {
        var cards = ctx.api.data.listCards();
        var columns = {};
        defaultColumns.forEach(function(col) { columns[col] = []; });
        columns['Untagged'] = [];
        cards.forEach(function(card) {
          var placed = false;
          if (card.tags && card.tags.length > 0) {
            card.tags.forEach(function(tag) {
              var normalized = tag.charAt(0).toUpperCase() + tag.slice(1).toLowerCase();
              var matched = defaultColumns.find(function(dc) { return dc.toLowerCase() === tag.toLowerCase(); });
              var colName = matched || normalized;
              if (!columns[colName]) columns[colName] = [];
              if (!placed) {
                columns[colName].push(card);
                placed = true;
              }
            });
          }
          if (!placed) columns['Untagged'].push(card);
        });
        var html = '';
        var columnOrder = defaultColumns.concat(Object.keys(columns).filter(function(k) {
          return defaultColumns.indexOf(k) === -1 && k !== 'Untagged';
        }));
        columnOrder.push('Untagged');
        columnOrder.forEach(function(colName) {
          var colCards = columns[colName] || [];
          html += '<div class="kanban-column">';
          html += '<div class="kanban-column-header">' + escapeHtml(colName);
          html += ' <span class="kanban-column-count">' + colCards.length + '</span></div>';
          html += '<div class="kanban-column-body">';
          colCards.forEach(function(card) {
            var bodyPreview = (card.body || '').substring(0, 80);
            html += '<div class="kanban-card" data-card-id="' + card.id + '">';
            html += '<div class="kanban-card-title">' + escapeHtml(card.title || 'Untitled') + '</div>';
            if (bodyPreview) {
              html += '<div class="kanban-card-body">' + escapeHtml(bodyPreview) + '</div>';
            }
            if (card.tags && card.tags.length > 0) {
              html += '<div class="kanban-card-tags">';
              card.tags.forEach(function(t) {
                html += '<span class="kanban-card-tag">' + escapeHtml(t) + '</span>';
              });
              html += '</div>';
            }
            html += '</div>';
          });
          if (colCards.length === 0) {
            html += '<div style="text-align:center;color:#aaa;font-size:12px;padding:20px;">No cards</div>';
          }
          html += '</div></div>';
        });
        view.innerHTML = html;
      }
      toggle.onclick = function() {
        self._kanbanActive = !self._kanbanActive;
        if (self._kanbanActive) {
          renderKanban();
          view.classList.add('active');
          toggle.textContent = 'Close Kanban';
        } else {
          view.classList.remove('active');
          toggle.textContent = 'Kanban View';
        }
      };
      self._renderKanban = renderKanban;
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'kanban-board-update',
          priority: -100,
          operations: ['card.save', 'card.delete'],
          handler: async function(mwCtx, next) {
            await next();
            if (self._kanbanActive) {
              setTimeout(function() { renderKanban(); }, 100);
            }
          }
        });
      }
      self._handleEscape = function(e) {
        if (e.key === 'Escape' && self._kanbanActive) {
          toggle.click();
        }
      };
      document.addEventListener('keydown', self._handleEscape);
      ctx.logger.info('Kanban Board loaded');
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('kanban-board-update');
      }
      if (this._handleEscape) {
        document.removeEventListener('keydown', this._handleEscape);
      }
      if (this._toggle && this._toggle.parentNode) this._toggle.remove();
      if (this._view && this._view.parentNode) this._view.remove();
      ctx.logger.info('Kanban Board disabled');
    }
  });
})();
